package com.smarthub.plus;
import android.content.*;
import android.os.*;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.text.InputType;
import android.view.*;
import android.widget.*;
/** Remote-operable timing panel. Buttons change cue offset, never the programme clock. */
final class SubtitleSyncControls extends LinearLayout {
 private final Handler clock=new Handler(Looper.getMainLooper());private final TextView file,state,timer,preview;private final EditText precise;private boolean attached;
 private final Runnable tick=new Runnable(){public void run(){if(!attached)return;refresh();clock.postDelayed(this,200);}};
 SubtitleSyncControls(Context c){super(c);setOrientation(VERTICAL);setPadding(dp(10),dp(8),dp(10),dp(8));setLayoutDirection(ar()?LAYOUT_DIRECTION_RTL:LAYOUT_DIRECTION_LTR);GradientDrawable bg=new GradientDrawable();bg.setColor(0xec102534);bg.setCornerRadius(dp(10));setBackground(bg);addView(label(tx("مزامنة الترجمة · مستقلة عن EPG","Subtitle synchronization · independent of EPG"),18,true));file=label("",13,false);addView(file);state=label("",15,true);addView(state);timer=label("",14,false);addView(timer);LinearLayout buttons=row();addButton(buttons,tx("تقديم 5ث","Advance 5s"),()->change(-5000));addButton(buttons,"−1 s",()->change(-1000));addButton(buttons,"−100 ms",()->change(-100));addButton(buttons,"+100 ms",()->change(100));addButton(buttons,"+1 s",()->change(1000));addButton(buttons,tx("تأخير 5ث","Delay 5s"),()->change(5000));addView(buttons);LinearLayout exact=row();precise=new EditText(c);precise.setTextColor(Color.WHITE);precise.setHintTextColor(0xffb4cadb);precise.setHint(tx("التأخير بالميلي ثانية","Delay milliseconds"));precise.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);precise.setSingleLine();exact.addView(precise,new LayoutParams(0,dp(48),1));addButton(exact,tx("تطبيق","Apply"),()->{try{SubtitleSyncRepository.set(c,Long.parseLong(precise.getText().toString().trim()));refresh();}catch(Exception e){Toast.makeText(c,tx("أدخل قيمة صحيحة بالميلي ثانية","Enter an integer millisecond value"),Toast.LENGTH_SHORT).show();}});addButton(exact,tx("إعادة للصفر","Reset to zero"),()->{SubtitleSyncRepository.set(c,0);precise.setText("0");refresh();});addView(exact);preview=label("",13,false);preview.setMaxLines(2);addView(preview);addView(label(tx("الضبط يدوي؛ توقيت EPG لا يكتشف تطابق الحوار مع الصوت.","Manual correction; EPG timing cannot detect dialogue/audio alignment."),12,false));LinearLayout actions=row();addButton(actions,tx("مشاركة التوقيت اختيارياً","Share timing optionally"),this::share);addView(actions);CaptionAppearance.controls(this,ar(),null);refresh();}
 private boolean ar(){return getContext().getSharedPreferences("smarthub",0).getBoolean("arabic",true);}private String tx(String a,String e){return ar()?a:e;}
 private boolean active(){android.content.SharedPreferences p=getContext().getSharedPreferences("smarthub",0);if(p.getString("subtitle_file_identity","").isEmpty())return false;if(PlaybackClock.visible||!p.getBoolean("satellite_companion_enabled",false))return true;SatelliteState s=SatelliteState.read(getContext());return s.channelId.equals(p.getString("subtitle_channel_id",""))&&s.startMs==p.getLong("subtitle_event_start_ms",0);}
 private void change(long delta){if(!active()){Toast.makeText(getContext(),tx("اختر ترجمة للبرنامج الحالي أولاً","Select this programme subtitle first"),Toast.LENGTH_SHORT).show();return;}long value=SubtitleSyncRepository.adjust(getContext(),delta);precise.setText(Long.toString(value));refresh();}
 private void refresh(){android.content.SharedPreferences p=getContext().getSharedPreferences("smarthub",0);long delay=SubtitleSyncRepository.offset(getContext());file.setText((active()?"":tx("غير نشطة · ","Inactive · "))+p.getString("subtitle_provider","")+" · "+p.getString("subtitle_display_name",tx("لم يُحدد ملف ترجمة","No subtitle file selected")));state.setText(tx("التزامن: ","Offset: ")+String.format(java.util.Locale.ROOT,"%+.3f s  (%+d ms)",delay/1000.0,delay));timer.setText(tx("مؤقت ملف الترجمة: ","Subtitle file clock: ")+ProgrammeClock.format(Math.max(0,CaptionClock.positionMs-delay),true)+(CaptionClock.playing?tx(" · تشغيل"," · playing"):tx(" · متوقف"," · paused")));preview.setText(tx("معاينة: ","Preview: ")+CaptionClock.text);}
 private void share(){try{org.json.JSONArray records=new org.json.JSONArray().put(SubtitleSyncRepository.exportCurrent(getContext()));String json=new org.json.JSONObject().put("format","SmartHubPlusShare").put("version",1).put("settings",new org.json.JSONObject()).put("subtitle_timings",records).toString(2);Intent send=new Intent(Intent.ACTION_SEND).setType("application/json").putExtra(Intent.EXTRA_TEXT,json);getContext().startActivity(Intent.createChooser(send,tx("مشاركة توقيت الترجمة","Share subtitle timing")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}catch(Exception e){Toast.makeText(getContext(),tx("لا يتوفر تطبيق مشاركة","No sharing application is available"),Toast.LENGTH_SHORT).show();}}
 private LinearLayout row(){LinearLayout r=new LinearLayout(getContext());r.setGravity(Gravity.CENTER_VERTICAL);return r;}
 private void addButton(LinearLayout row,String title,Runnable click){Button b=new Button(getContext());b.setText(title);b.setTextSize(12);b.setAllCaps(false);b.setFocusable(true);b.setOnClickListener(v->click.run());row.addView(b,new LayoutParams(0,dp(48),1));}
 private TextView label(String text,int size,boolean bold){TextView t=new TextView(getContext());t.setText(text);t.setTextColor(Color.WHITE);t.setTextSize(size);t.setTextDirection(TEXT_DIRECTION_FIRST_STRONG);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
 private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();attached=true;clock.post(tick);}
 @Override protected void onDetachedFromWindow(){attached=false;clock.removeCallbacksAndMessages(null);super.onDetachedFromWindow();}
}
